INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A dye costs $18 per kg. If a recipe uses 2.2% owf for a 750 kg fabric batch, what is the approximate total dye cost?', '["≈ $297","≈ $18","≈ $16.50","≈ $1,650"]'::jsonb, '≈ $297', 'Dye needed = 0.022 × 750 kg = 16.5 kg. Total cost = 16.5 kg × $18/kg = $297.', 2, '{"dye-cost-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A dye costs $12 per kg. If a recipe uses 3% owf for a 400 kg fabric batch, what is the approximate total dye cost?', '["≈ $144","≈ $12","≈ $36","≈ $1,200"]'::jsonb, '≈ $144', 'Dye needed = 0.03 × 400 kg = 12 kg. Total cost = 12 kg × $12/kg = $144.', 2, '{"dye-cost-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A stenter processes fabric at 35 meters per minute for a 12-hour shift at 88% uptime. Approximately how many meters of fabric are processed?', '["≈ 22,176 meters","≈ 25,200 meters","≈ 35 meters","≈ 420 meters"]'::jsonb, '≈ 22,176 meters', 'At 100% uptime: 35 m/min × 720 min = 25,200 meters. At 88% uptime: 25,200 × 0.88 = 22,176 meters.', 2, '{"stenter-production-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A finishing chemical is applied at 3% add-on (by weight) on a 900 kg fabric batch. How many kg of chemical are added?', '["27 kg","3 kg","300 kg","9 kg"]'::jsonb, '27 kg', 'Add-on = 3% × fabric weight = 0.03 × 900 kg = 27 kg.', 1, '{"addon-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A mill''s ETP handles 45,000 liters per day, and a planned expansion increases fabric processing volume by 20%. Assuming proportional water use, what is the new approximate daily ETP volume needed?', '["54,000 liters","45,000 liters","36,000 liters","63,000 liters"]'::jsonb, '54,000 liters', 'New volume = old volume × (1 + increase%) = 45,000 × 1.20 = 54,000 liters.', 1, '{"etp-scaleup-calc"}'::text[]);
